<?php
declare(strict_types=1);
return static function(PDO $db):void{
    $db->exec("CREATE TABLE IF NOT EXISTS suppliers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,address VARCHAR(255) NULL,phone VARCHAR(80) NULL,email VARCHAR(190) NULL,tax_number VARCHAR(100) NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_supplier_name(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $db->exec("CREATE TABLE IF NOT EXISTS internal_purchase_orders(id INT AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(80) NOT NULL,feb_id INT NOT NULL,supplier_id INT NOT NULL,amount DECIMAL(15,2) NOT NULL,delivery_date DATE NULL,status VARCHAR(30) NOT NULL DEFAULT 'issued',created_by INT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,document_uid VARCHAR(80) NOT NULL,UNIQUE KEY uniq_ipo_feb(feb_id),UNIQUE KEY uniq_ipo_number(order_number),UNIQUE KEY uniq_ipo_uid(document_uid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $db->exec("CREATE TABLE IF NOT EXISTS disbursement_authorizations(id INT AUTO_INCREMENT PRIMARY KEY,authorization_number VARCHAR(80) NOT NULL,feb_id INT NOT NULL,internal_order_id INT NOT NULL,supplier_id INT NOT NULL,beneficiary_name VARCHAR(190) NOT NULL,amount DECIMAL(15,2) NOT NULL,planned_date DATE NULL,status VARCHAR(30) NOT NULL DEFAULT 'purchase_validation',approved_by INT NOT NULL,approved_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,approver_signature VARCHAR(255) NOT NULL,document_uid VARCHAR(80) NOT NULL,UNIQUE KEY uniq_authorization_feb(feb_id),UNIQUE KEY uniq_authorization_number(authorization_number),UNIQUE KEY uniq_authorization_uid(document_uid),INDEX idx_authorization_purchase(status,planned_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
};
